# ----------------------------------------------------------------------
# Section: Simulated Residuals and GOF in R
# ----------------------------------------------------------------------
set.seed(20260731)
library(dplyr)
library(ggplot2)
library(tidyr)

# Simulate population PK
n_sub <- 30
times <- c(0.5, 1, 2, 4, 8, 12)
CL_pop <- 5; V_pop <- 50; D <- 500
omega <- 0.25; prop_sd <- 0.10

sim <- expand_grid(ID = 1:n_sub, TIME = times) |>
  mutate(
    CL = CL_pop * exp(rnorm(n_sub, 0, omega)[ID]),
    V  = V_pop,
    k  = CL / V,
    IPRED = (D / V) * exp(-k * TIME),
    PRED  = (D / V_pop) * exp(-(CL_pop / V_pop) * TIME)
  ) |>
  mutate(
    DV = IPRED * exp(rnorm(n(), 0, prop_sd))
  )

# Approximate IWRES under proportional error (not CWRES)
sim <- sim |>
  mutate(
    IWRES = (DV - IPRED) / (IPRED * prop_sd),
    # Approximate population residual (PRED scale; informal teaching aid)
    PWRES = (DV - PRED) / (PRED * prop_sd)
  )

p1 <- ggplot(sim, aes(PRED, DV)) +
  geom_point(alpha = 0.5) +
  geom_abline(slope = 1, intercept = 0, linetype = 2) +
  scale_x_log10() + scale_y_log10() +
  labs(title = "Observed vs population predicted") +
  theme_minimal()

p2 <- ggplot(sim, aes(TIME, IWRES)) +
  geom_point(alpha = 0.5) +
  geom_hline(yintercept = 0, linetype = 2) +
  geom_hline(yintercept = c(-2, 2), linetype = 3, alpha = 0.5) +
  labs(title = "IWRES vs time") +
  theme_minimal()

p3 <- ggplot(sim, aes(sample = IWRES)) +
  stat_qq() + stat_qq_line() +
  labs(title = "QQ plot of IWRES") +
  theme_minimal()

# Display side by side (patchwork optional; use grid)
print(p1)
print(p2)
print(p3)

